-- Generated by generate_skill_affixes.py from D3Planner statGroups and the class catalogue.
-- diablocraft-class-roll-rules rule 6: each playable class's own skill-affix choices in the
-- slot groups the affix pool rolls. The server rolls only the choices of the item's class
-- (dc_roll_class.h). Classes with no generated catalogue get no rows yet.
-- Backstop, as items_0005: a row left without a skill_id aborts on a duplicate key.
DROP TEMPORARY TABLE IF EXISTS dc_skill_affix_abort;
CREATE TEMPORARY TABLE dc_skill_affix_abort (reason VARCHAR(190) NOT NULL, PRIMARY KEY (reason)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
  SELECT 'MIGRATION ABORTED - a dc_skill_affix row has no skill_id. Re-run generate_skill_affixes.py and re-import the affix migrations' FROM dc_skill_affix WHERE skill_id = 0
  UNION ALL
  SELECT 'MIGRATION ABORTED - a dc_skill_affix row has no skill_id. Re-run generate_skill_affixes.py and re-import the affix migrations' FROM dc_skill_affix WHERE skill_id = 0;
DROP TEMPORARY TABLE IF EXISTS dc_skill_affix_abort;
